efore{content:'';width:6px;height:6px;border-radius:50%;background:#20a365}.appt-count{display:inline-flex;background:#fff0d9;color:#96550a;border-radius:7px;padding:4px 6px;font-size:10px;font-weight:800}.closed-label{background:#fff0ed;color:#a64d37;border-radius:7px;padding:4px 6px;font-size:10px;font-weight:700}.event-chip{display:block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;background:#e8f4fa;color:#205c78;border-radius:6px;padding:4px 6px}.event-chip.pending{background:#fff0d9;color:#8b590d}.event-chip.cancelled,.event-chip.rejected{background:#ffeded;color:#a63c3c}.agenda-legend{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px;color:#638091;font-size:11px}.calendar-modal{position:fixed;inset:0;margin:auto;width:min(680px,calc(100vw - 28px));max-height:min(88vh,900px);overflow:auto;border:1px solid #d9e9f0;border-radius:20px;padding:0;box-shadow:0 30px 100px #163d5150;color:#243f50}.calendar-modal::backdrop{background:#122f4080;backdrop-filter:blur(5px)}.calendar-modal>header{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:17px 21px;background:#f2f9fc;border-bottom:1px solid #dceaf1}.calendar-modal>header h2{margin:2px 0 0;font-size:20px}.calendar-modal .modal-content{padding:20px}.calendar-modal .modal-close{width:34px;height:34px;padding:0;background:#e1f0f6;color:#24546c;border:0;border-radius:10px;font-size:21px}.calendar-form{border-top:1px solid #e3edf2;margin-top:18px;padding-top:17px}.calendar-form h3{margin:0 0 5px}.calendar-form .formgrid{grid-template-columns:repeat(2,minmax(0,1fr))}.calendar-form input[type=time]{min-height:43px}.calendar-form .button-main{background:#f28c28;color:#fff;border:1px solid #f28c28;padding:9px 14px;border-radius:10px;font-size:13px;font-weight:800}.calendar-form .button-secondary{background:#f1f8fb;color:#28576d;border:1px solid #d7e8ef;padding:9px 14px;border-radius:10px;font-size:13px;font-weight:700}.booking-card{border:1px solid #dfebf1;border-radius:12px;padding:12px;margin:9px 0}.booking-card .meta{font-size:12px;color:#5b7a8b}.closure-form{display:grid;grid-template-columns:minmax(140px,.7fr) minmax(180px,1.3fr) auto;gap:12px;align-items:end}.closure-form label{margin-top:0}@media(max-width:760px){.agenda-card{padding:11px}.calendar-day{min-height:76px;padding:4px;gap:3px}.day-number{width:23px;height:23px}.day-meta,.open-label,.appt-count,.closed-label,.event-chip{font-size:9px}.calendar-modal .modal-content{padding:13px}.closure-form{grid-template-columns:1fr}.agenda-controls button,.agenda-controls select{padding:8px}.calendar-form .formgrid{grid-template-columns:1fr}}
</style>
