  <div class="agenda-toolbar"><div><div class="muted" style="letter-spacing:.12em;font-weight:800">KALENDER · VERFÜGBARKEIT</div><h2 id="calendar-title">Kalender</h2><p class="muted" style="margin:4px 0 0">Klicke auf einen Tag, um deine Verfügbarkeit festzulegen.</p></div><div class="agenda-controls"><button type="button" id="calendar-prev" aria-label="Vorheriger Zeitraum">‹ Zurück</button><button type="button" id="calendar-today" class="agenda-primary">Heute</button><button type="button" id="calendar-next" aria-label="Nächster Zeitraum">Weiter ›</button><select id="calendar-view" aria-label="Kalenderansicht"><option value="month">Monat</option><option value="week">Woche</option></select></div></div>
