<dialog id="calendar-day-modal" class="calendar-modal"><header><div><div class="muted" style="letter-spacing:.1em;font-weight:800">TAGESVERWALTUNG</div><h2 id="day-modal-title">Datum auswählen</h2></div><button type="button" class="modal-close" id="day-modal-close" aria-label="Schließen">×</button></header><div class="modal-content"><div id="day-modal-bookings"></div><form class="calendar-form" method="post" action="{{ route('admin.agenda.day.save') }}" id="day-hours-form">@csrf<input type="hidden" name="override_date" id="override-date"><h3>Verfügbarkeit für diesen Tag</h3><p class="muted">Standardmäßig bist du nicht verfügbar. Aktiviere „Geöffnet“ nur an Tagen, an denen du Termine annehmen kannst.</p><label style="display:flex;align-items:center;gap:9px;margin:15px 0"><input type="checkbox" name="is_open" id="day-is-open" value="1" style="width:18px;height:18px"> <span style="font-size:14px">Geöffnet · Ich bin an diesem Tag verfügbar</span></label><div id="day-time-fields" class="formgrid" hidden><div><label for="day-open">Geöffnet von</label><input id="day-open" name="open_time" type="time" value="09:00"></div><div><label for="day-close">Geöffnet bis</label><input id="day-close" name="close_time" type="time" value="18:00"></div></div><div style="margin-top:12px"><label for="day-label">Notiz (optional)</label><input id="day-label" name="label" maxlength="150" placeholder="Zum Beispiel: nur am Nachmittag verfügbar"></div><div id="conflict-choice" hidden><label for="conflict-action">Bereits gebuchte Termine</label><select id="conflict-action" name="conflict_action"><option value="">Aktion wählen, bevor der Tag geschlossen wird</option><option value="cancel">Termine stornieren</option><option value="reject">Anfragen ablehnen</option></select></div><div class="row" style="margin-top:16px"><button type="submit" class="button-main">Verfügbarkeit speichern</button><button type="button" class="button-secondary" id="day-modal-cancel">Abbrechen</button></div></form></div></dialog>
<section class="panel"><div class="row" style="justify-content:space-between"><div><h2>Ausnahmen und Urlaub</h2><p class="muted">Nutze diese Liste für Tage, an denen du unabhängig von deinen eingetragenen Verfügbarkeiten geschlossen bist.</p></div></div><form class="closure-form" method="post" action="{{ route('admin.closures.store') }}">@csrf<div><label for="closure-date">Datum</label><input id="closure-date" type="date" name="closure_date" min="{{ today()->toDateString() }}" required></div><div><label for="closure-label">Grund</label><input id="closure-label" name="label" placeholder="Urlaub, private Termine …"></div><button type="submit">Ausnahme hinzufügen</button></form><div class="scroll" style="margin-top:16px"><table><thead><tr><th>Datum</th><th>Grund</th><th>Aktion</th></tr></thead><tbody>@forelse($closures as $closure)<tr><td>{{ $closure->closure_date->format('d.m.Y') }}</td><td>{{ $closure->label ?: 'Geschlossen' }}</td><td><form method="post" action="{{ route('admin.closures.destroy',$closure) }}">@csrf @method('DELETE')<button type="submit" class="danger">Entfernen</button></form></td></tr>@empty<tr><td colspan="3">Keine Ausnahmen eingetragen.</td></tr>@endforelse</tbody></table></div></section>
<script>
(()=>{
 const eventsUrl=@json(route('admin.agenda.events')),dayUrl=@json(route('admin.agenda.day')),grid=document.getElementById('calendar-grid'),title=document.getElementById('calendar-title'),status=document.getElementById('calendar-status'),viewSelect=document.getElementById('calendar-view'),dialog=document.getElementById('calendar-day-modal');
 const locale='de-DE';let cursor=new Date();cursor.setDate(1);let events=[];const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const startOfWeek=d=>{const x=new Date(d);x.setDate(x.getDate()-(x.getDay()+6)%7);x.setHours(0,0,0,0);return x};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 async function load(){const mode=viewSelect.value;let start,end;if(mode==='month'){start=startOfWeek(new Date(cursor.getFullYear(),cursor.getMonth(),1));end=new Date(start);end.setDate(start.getDate()+42)}else{start=startOfWeek(cursor);end=new Date(start);end.setDate(start.getDate()+7)}title.textContent=mode==='month'?cursor.toLocaleDateString(locale,{month:'long',year:'numeric'}):`${start.toLocaleDateString(locale,{day:'numeric',month:'short'})} – ${new Date(end-1).toLocaleDateString(locale,{day:'numeric',month:'short',year:'numeric'})}`;grid.innerHTML='<div style="padding:20px">Kalender wird geladen …</div>';try{const u=new URL(eventsUrl,location.origin);u.searchParams.set('start',iso(start));u.searchParams.set('end',iso(end));const r=await fetch(u,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});if(!r.ok)throw Error();events=await r.json();render(start,end,mode);status.textContent='Kalender aktualisiert.'}catch(e){grid.innerHTML='<p style="padding:16px">Kalender konnte nicht geladen werden. Bitte aktualisieren.</p>';status.textContent='Ladefehler.'}}
 function render(start,end,mode){grid.innerHTML='';['Mo','Di','Mi','Do','Fr','Sa','So'].forEach(x=>{const e=document.createElement('div');e.className='calendar-weekday';e.textContent=x;grid.appendChild(e)});let d=new Date(start);while(d<end){const date=iso(d),sameMonth=d.getMonth()===cursor.getMonth(),dayEvents=events.filter(e=>e.start?.slice(0,10)===date),appts=dayEvents.filter(e=>e.kind==='booking'&&!['cancelled','rejected'].includes(e.status)),availability=dayEvents.find(e=>e.kind==='availability'),closed=dayEvents.some(e=>e.kind==='closure')||(availability&&!availability.is_open);const btn=document.createElement('button');btn.type='button';btn.className='calendar-day'+(sameMonth?'':' outside')+(date===iso(new Date())?' today':'');btn.dataset.date=date;btn.innerHTML=`<span class="day-number">${d.getDate()}</span>`;if(availability?.is_open){btn.insertAdjacentHTML('beforeend',`<span class="open-label">Geöffnet</span><span class="day-meta">${esc(availability.open_time||'09:00')} – ${esc(availability.close_time||'18:00')}</span>`)}else if(closed){btn.insertAdjacentHTML('beforeend','<span class="closed-label">Geschlossen</span>')}if(appts.length)btn.insertAdjacentHTML('beforeend',`<span class="appt-count">${appts.length} ${appts.length===1?'Termin':'Termine'}</span>`);appts.slice(0,2).forEach(e=>{const chip=document.createElement('span');chip.className='event-chip '+e.status;chip.textContent=e.title;btn.appendChild(chip)});if(appts.length>2){const more=document.createElement('span');more.className='day-meta';more.textContent=`+${appts.length-2} weitere`;btn.appendChild(more)}btn.addEventListener('click',()=>openDay(date));grid.appendChild(btn);d.setDate(d.getDate()+1)}}
 async function openDay(date){document.getElementById('day-modal-title').textContent=new Date(date+'T12:00:00').toLocaleDateString(locale,{weekday:'long',day:'numeric',month:'long',year:'numeric'});document.getElementById('override-date').value=date;document.getElementById('day-modal-bookings').innerHTML='<p class="muted">Termine werden geladen …</p>';document.getElementById('conflict-choice').hidden=true;document.getElementById('conflict-action').value='';dialog.showModal();try{const u=new URL(dayUrl,location.origin);u.searchParams.set('date',date);const r=await fetch(u,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});if(!r.ok)throw Error();const d=await r.json(),active=d.bookings.filter(b=>['pending','confirmed'].includes(b.status));let html='';if(d.closure)html+=`<p class="closed-label">Ausnahme: ${esc(d.closure)}</p>`;if(d.bookings.length){html+='<h3>Termine an diesem Tag</h3>'+d.bookings.map(b=>`<article class="booking-card"><strong>${esc(b.time)}${b.end?' – '+esc(b.end):''} · ${esc(b.customer)}</strong><div class="meta">${esc(b.service)} · ${b.mode==='home'?'Hausbesuch':'Im Salon'} · ${esc(b.status)} · ${esc(b.total)} €</div><div class="meta">${esc(b.email)} · ${esc(b.phone)}</div><p style="margin:8px 0 0"><a class="button-secondary" href="{{ route('admin.bookings.index') }}?date=${encodeURIComponent(date)}">Termin verwalten</a></p></article>`).join('')+`<p class="muted">${active.length} aktive Termine. Beim Schließen musst du angeben, wie sie behandelt werden.</p>`}else html+='<p class="muted">Für diesen Tag sind keine Termine eingetragen.</p>';document.getElementById('day-modal-bookings').innerHTML=html;const o=d.override;const isOpen=!!(o&&o.is_open);document.getElementById('day-is-open').checked=isOpen;document.getElementById('day-time-fields').hidden=!isOpen;document.getElementById('day-open').value=o?.open_time||'09:00';document.getElementById('day-close').value=o?.close_time||'18:00';document.getElementById('day-label').value=o?.label||'';document.getElementById('conflict-choice').hidden=!(active.length>0);if(d.closure&&!isOpen)document.getElementById('day-is-open').checked=false}catch(e){document.getElementById('day-modal-bookings').innerHTML='<p>Details konnten nicht geladen werden.</p>'}}
 document.getElementById('day-is-open').addEventListener('change',e=>{document.getElementById('day-time-fields').hidden=!e.target.checked;const hasActive=document.querySelectorAll('#day-modal-bookings .booking-card').length>0;document.getElementById('conflict-choice').hidden=e.target.checked||!hasActive});document.getElementById('day-hours-form').addEventListener('submit',e=>{if(document.getElementById('day-is-open').checked&&document.getElementById('day-close').value<=document.getElementById('day-open').value){e.preventDefault();alert('Die Endzeit muss nach der Startzeit liegen.')}else if(!document.getElementById('day-is-open').checked&&!document.getElementById('conflict-choice').hidden&&!document.getElementById('conflict-action').value){e.preventDefault();alert('Bitte wähle eine Aktion für bestehende Termine.')}});
 document.getElementById('calendar-prev').addEventListener('click',()=>{if(viewSelect.value==='month')cursor.setMonth(cursor.getMonth()-1);else cursor.setDate(cursor.getDate()-7);load()});document.getElementById('calendar-next').addEventListener('click',()=>{if(viewSelect.value==='month')cursor.setMonth(cursor.getMonth()+1);else cursor.setDate(cursor.getDate()+7);load()});document.getElementById('calendar-today').addEventListener('click',()=>{cursor=new Date();cursor.setDate(1);load()});viewSelect.addEventListener('change',load);document.getElementById('day-modal-close').addEventListener('click',()=>dialog.close());document.getElementById('day-modal-cancel').addEventListener('click',()=>dialog.close());load();
})();
</script>
@endsection
